const fs = require('fs/promises');
const path = require('path');
const { AppError } = require('../../utils/errors');

// Local-disk driver for the PUBLIC car photos. Files live under `rootDir` and are served by express.static at
// `${publicBaseUrl}/uploads/<key>`. Identity documents never use this driver (see ./private.js).
// Every other driver (S3, R2, ...) must expose the same methods: save, keyFromUrl, removeByUrl.

// Keys are generated by the server (cars/<partnerId>/<uuid>.<ext>); this is the only alphabet we accept back.
const SAFE_KEY = /^[A-Za-z0-9_\-]+(?:\/[A-Za-z0-9_\-.]+)+$/;

const LOCAL_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]']);

module.exports = function createLocalDriver({ rootDir, publicBaseUrl }) {
  rootDir = path.resolve(rootDir);
  const base = new URL(publicBaseUrl); // throws early on an invalid base URL
  const urlPrefix = `${base.origin}/uploads/`;

  // Resolves a key to a path and refuses anything that would leave rootDir.
  const resolveKey = (key) => {
    const full = path.resolve(rootDir, key);
    if (full !== rootDir && !full.startsWith(rootDir + path.sep)) throw new Error('Invalid storage key');
    return full;
  };

  // Turns a stored URL into a storage key, or null when the URL is not one of ours.
  // Besides the current public URL it also understands URLs saved by older setups that pointed at
  // localhost (e.g. http://localhost:5000/uploads/cars/1/x.jpg) and site-relative "/uploads/..." paths, so
  // ownership checks and file cleanup keep working for rows that were stored before PUBLIC_BASE_URL was fixed.
  const keyFromUrl = (url) => {
    if (typeof url !== 'string') return null;
    let pathname;
    if (url.startsWith('/') && !url.startsWith('//')) {
      pathname = url.split(/[?#]/)[0];
    } else {
      let u;
      try {
        u = new URL(url);
      } catch {
        return null;
      }
      const ours = u.origin === base.origin;
      const legacyLocal = (u.protocol === 'http:' || u.protocol === 'https:') && LOCAL_HOSTS.has(u.hostname);
      if (!ours && !legacyLocal) return null;
      pathname = u.pathname;
    }
    if (!pathname.startsWith('/uploads/')) return null;
    let key;
    try {
      key = decodeURIComponent(pathname.slice('/uploads/'.length));
    } catch {
      return null;
    }
    return SAFE_KEY.test(key) && !key.includes('..') ? key : null;
  };

  return {
    name: 'local',
    rootDir,
    urlPrefix,

    /** Creates the upload folder if needed and proves the process can write to it. Never throws. */
    async check() {
      const result = { rootDir, writable: false, error: null };
      try {
        await fs.mkdir(rootDir, { recursive: true });
        const probe = path.join(rootDir, `.write-test-${process.pid}-${Date.now()}`);
        await fs.writeFile(probe, 'ok', { flag: 'wx' });
        await fs.unlink(probe);
        result.writable = true;
      } catch (err) {
        result.error = `${err.code || 'ERROR'}: ${err.message}`;
      }
      return result;
    },

    /** Saves a Buffer under `key` and returns its public HTTPS URL. */
    async save({ key, buffer }) {
      if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error('Invalid storage key');
      const full = resolveKey(key);
      try {
        await fs.mkdir(path.dirname(full), { recursive: true });
        await fs.writeFile(full, buffer, { flag: 'wx', mode: 0o644 }); // 'wx': never overwrite
      } catch (err) {
        console.error(`Could not store uploaded image (${err.code || 'ERROR'}) in ${rootDir}: ${err.message}`);
        throw new AppError('Image storage is not available right now. Please try again later.', 500);
      }
      const url = urlPrefix + key;
      new URL(url); // never hand out a malformed URL
      return { key, url };
    },

    /** The storage key for a URL this driver produced (or an older local URL of ours), or null. */
    keyFromUrl,

    /** Best-effort delete of the file behind a URL. Unknown URLs are ignored. */
    async removeByUrl(url) {
      const key = keyFromUrl(url);
      if (!key) return;
      try {
        await fs.unlink(resolveKey(key));
      } catch (err) {
        if (err.code !== 'ENOENT') console.error('Could not delete uploaded file:', err.message);
      }
    },
  };
};
